import{_ as a}from"./chunks/difficulty_hard.N1nnc_xq.js";import{_ as t}from"./chunks/remote_control.ss1psCxn.js";import{_ as r}from"./chunks/acrobatic_fw.V5ocxbfx.js";import{_ as o,o as _,c as d,al as i}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"Режим Acro (фіксоване крило)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes_fw/acro.md","filePath":"uk/flight_modes_fw/acro.md"}'),c={name:"uk/flight_modes_fw/acro.md"};function l(n,e,m,s,h,f){return _(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="режим-acro-фіксоване-крило" tabindex="-1">Режим Acro (фіксоване крило) <a class="header-anchor" href="#режим-acro-фіксоване-крило" aria-label="Permalink to &quot;Режим Acro (фіксоване крило)&quot;">​</a></h1><p><img src="'+a+'" title="Hard to fly" width="30px"> <img src="'+t+'" title="Manual/Remote control required" width="30px"> </p><p><em>Acro mode</em> is the manual mode for performing acrobatic maneuvers e.g. rolls, flips, stalls and acrobatic figures.</p><p>Ручки крена, тангажу та риштування керують швидкістю кутової обертання навколо відповідних вісей, а керування тяги безпосередньо передається до розподілу керування. Коли стіки будуть відцентровані, апарат перестане обертатися, але залишиться у своїй поточній орієнтації (на боці, перевернутий, тощо) і рухатиметься відповідно до свого поточного імпульсу.</p><p><img src="'+r+'" alt="FW Manual Acrobatic Flight"></p><h2 id="технічнии-опис" tabindex="-1">Технічний опис <a class="header-anchor" href="#технічнии-опис" aria-label="Permalink to &quot;Технічний опис&quot;">​</a></h2><p>Ручний режим для виконання акробатичних маневрів, наприклад, перекидів, сальто, стійок і акробатичних фігур.</p><p>Вхідні сигнали стіків крену-тангажу перетворюються на команди кутової швидкості, які стабілізуються автопілотом. Передача дроселя здійснюється безпосередньо для керування розподілом.</p><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_manual_control"><code>mode_req_manual_control</code></a> — Requires stick input</li></ul><h2 id="параметри" tabindex="-1">Параметри <a class="header-anchor" href="#параметри" aria-label="Permalink to &quot;Параметри&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="FW_ACRO_X_MAX"></a><a href="./../advanced_config/parameter_reference#FW_ACRO_X_MAX">FW_ACRO_X_MAX</a></td><td>Максимальна швидкість обертання корпусу x (швидкість обертання корпусу x, яку контролер намагається досягти, якщо користувач вводить ролл-стік в режимі acro). За замовчуванням: 90 градусів.</td></tr><tr><td><a id="FW_ACRO_Y_MAX"></a><a href="./../advanced_config/parameter_reference#FW_ACRO_Y_MAX">FW_ACRO_Y_MAX</a></td><td>Максимальна швидкість тіла y в режимі acro (максимальна швидкість тіла y, якої намагається досягти контролер, якщо користувач вводить пітч-стик у режимі acro). За замовчуванням: 90 градусів.</td></tr><tr><td><a id="FW_ACRO_Z_MAX"></a><a href="./../advanced_config/parameter_reference#FW_ACRO_Z_MAX">FW_ACRO_Z_MAX</a></td><td>Максимальна швидкість обертання корпусу z в режимі acro (максимальна швидкість обертання корпусу, якої намагається досягти контролер, якщо користувач вводить стик рискання в режимі acro). За замовчуванням: 45 градусів.</td></tr><tr><td><a id="FW_ACRO_YAW_EN"></a><a href="./../advanced_config/parameter_reference#FW_ACRO_YAW_EN">FW_ACRO_YAW_EN</a></td><td>Enable yaw rate controller (if disabled the pilot commands directly the yaw actuator). <code>0</code>: Disabled (Default), <code>1</code>: Enabled.</td></tr></tbody></table>',13)])])}const q=o(c,[["render",l]]);export{g as __pageData,q as default};
